gelu_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float fast_tanh(float x) {
    // Numerically stable fast tanh using __expf: tanh(x) = sign(x) * (1 - e) / (1 + e),
    // where e = exp(-2|x|) is always in (0, 1], so no overflow/NaN for large |x|.
    float ax = fabsf(x);
    float e = __expf(-2.0f * ax);
    float t = (1.0f - e) / (1.0f + e);
    return copysignf(t, x);
}
__device__ __forceinline__ float gelu_scalar(float v) {
    const float k0 = 0.79788456080286535588f; // sqrt(2/pi)
    const float k1 = 0.044715f;
    float v3 = v * v * v;
    float inner = k0 * (v + k1 * v3);
    float t = fast_tanh(inner);
    return 0.5f * v * (1.0f + t);
}

__global__ void __launch_bounds__(512) gelu_cute_kernel(const float4* __restrict__ X4,
                                 float4* __restrict__ Y4,
                                 const float* __restrict__ X1,
                                 float* __restrict__ Y1,
                                 int nvec,
                                 int rem,
                                 long long total)
{
    constexpr int Threads = 512;
    constexpr int Items   = 8;                    // float4 per thread per tile (more MLP)
    constexpr int Tile    = Threads * Items;      // float4 per CTA tile

    Tensor mX = make_tensor(make_gmem_ptr(X4), make_shape(nvec));
    Tensor mY = make_tensor(make_gmem_ptr(Y4), make_shape(nvec));

    const int tid = threadIdx.x;
    const int grid_stride = gridDim.x * Tile;

    for (int base = blockIdx.x * Tile; base < nvec; base += grid_stride) {
        if (base + Tile <= nvec) {
            // Full tile fast path: register-blocked streaming loads. Issue all
            // Items float4 loads back-to-back into registers first for maximum
            // memory-level parallelism per thread (more outstanding DRAM requests),
            // then compute+store. The register budget at this CTA residency absorbs
            // the 8xfloat4 tile without reducing occupancy on this DRAM-bound kernel.
            float4 r[Items];
            #pragma unroll
            for (int j = 0; j < Items; ++j) {
                r[j] = __ldcs(&X4[base + tid + j * Threads]);
            }
            #pragma unroll
            for (int j = 0; j < Items; ++j) {
                const int i = base + tid + j * Threads;
                float4 v = r[j];
                v.x = gelu_scalar(v.x);
                v.y = gelu_scalar(v.y);
                v.z = gelu_scalar(v.z);
                v.w = gelu_scalar(v.w);
                __stcs(&Y4[i], v);
            }
        } else {
            // Boundary tile: keep exact bounds checks (no OOB access).
            #pragma unroll
            for (int j = 0; j < Items; ++j) {
                int i = base + tid + j * Threads;
                if (i < nvec) {
                    float4 v = __ldcs(&X4[i]);
                    v.x = gelu_scalar(v.x);
                    v.y = gelu_scalar(v.y);
                    v.z = gelu_scalar(v.z);
                    v.w = gelu_scalar(v.w);
                    __stcs(&Y4[i], v);
                }
            }
        }
    }

    // Handle scalar tail inside the same kernel (streaming hints, no reuse).
    if (rem > 0 && blockIdx.x == 0 && tid < rem) {
        long long idx = (long long)nvec * 4 + tid;
        if (idx < total) {
            __stcs(&Y1[idx], gelu_scalar(__ldcs(&X1[idx])));
        }
    }
}

torch::Tensor gelu_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

    auto xc = x.contiguous();
    auto y = torch::empty_like(xc);

    const long long total = xc.numel();
    if (total == 0) {
        return y;
    }

    const int nvec = (int)(total / 4);
    const int rem  = (int)(total % 4);

    constexpr int Threads = 512;
    constexpr int Items   = 8;
    constexpr int Tile    = Threads * Items;

    int needed = (nvec + Tile - 1) / Tile;
    if (needed <= 0) needed = 1;
    // Launch-configuration fix (profiler-driven): the previous launch created a
    // partial wave (grid 1024 vs a 768-block full wave), which Nsight attributes
    // up to ~50% of the runtime to as tail effect, plus ~11% SM load imbalance.
    // Instead of assuming 8 CTAs/SM, query the real per-SM CTA residency with the
    // occupancy API and cap the grid at exactly one full wave (the grid-stride
    // loop covers the remaining tiles). The grid is also rounded down to a
    // multiple of the SM count so every SM receives identical work (no partial
    // wave and no cross-SM imbalance).
    static int sm_count = -1;
    static int wave_blocks = -1;
    if (sm_count < 0 || wave_blocks < 0) {
        cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, xc.get_device());
        if (sm_count <= 0) sm_count = 1;
        int cta_per_sm = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&cta_per_sm, gelu_cute_kernel, Threads, 0);
        if (cta_per_sm <= 0) cta_per_sm = 1;
        wave_blocks = sm_count * cta_per_sm;
        if (wave_blocks <= 0) wave_blocks = sm_count;
    }
    int blocks = needed < wave_blocks ? needed : wave_blocks;
    if (blocks > sm_count) {
        blocks = (blocks / sm_count) * sm_count; // exact whole waves, no tail
    }
    if (blocks <= 0) blocks = 1;

    const float* xptr = xc.data_ptr<float>();
    float* yptr = y.data_ptr<float>();

    const float4* x4 = reinterpret_cast<const float4*>(xptr);
    float4* y4 = reinterpret_cast<float4*>(yptr);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    gelu_cute_kernel<<<blocks, Threads, 0, stream>>>(x4, y4, xptr, yptr, nvec, rem, total);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "gelu_cute_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
